'use client';

/**
 * <RoxyVedicPlanetsTable data={...} />: Vedic planetary positions table with degree, nakshatra, pada, nakshatra lord, bhava, and avastha.
 *
 * You own this file. Customize freely. The component is re-exported from
 * @roxyapi/ui-react and stays in sync with the published package.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/vedic-planets-table/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   const { data } = await roxy.vedicAstrology.generateBirthChart({ body: await req.json() });
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyVedicPlanetsTable as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyVedicPlanetsTableProps = ComponentProps<typeof Element>;

export function RoxyVedicPlanetsTable(props: RoxyVedicPlanetsTableProps) {
	return <Element {...props} />;
}

export default RoxyVedicPlanetsTable;
